<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Find Result | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body><div class="main-wrapper"><div class="container" style="max-width:720px;margin:50px auto"><div class="panel"><div class="panel-heading"><h3 class="text-center">Student Result Search</h3></div><div class="panel-body"><form method="post" action="result.php"><?php echo csrf_field(); ?><div class="form-group"><label>Academic Year</label><input name="academic_year" class="form-control" required value="<?php echo e($_POST['academic_year']??date('Y').'/'.(date('Y')+1)); ?>" placeholder="2026/2027"></div><div class="form-group"><label>Term</label><select name="term" class="form-control"><option>Term 1</option><option>Term 2</option><option>Term 3</option><option selected>Final</option></select></div><div class="form-group"><label>Examination</label><input name="exam_type" class="form-control" required value="Final Examination"></div><div class="form-group"><label>Roll ID</label><input name="rollid" class="form-control" required maxlength="100"></div><div class="form-group"><label>Class</label><select name="class" class="form-control" required><option value="">Select Class</option><?php $q=$dbh->query('SELECT id,ClassName,Section FROM tblclasses ORDER BY ClassNameNumeric,Section'); while($r=$q->fetch()): ?><option value="<?php echo (int)$r['id']; ?>"><?php echo e($r['ClassName'].' Section-'.$r['Section']); ?></option><?php endwhile; ?></select></div><button class="btn btn-success pull-right">Search Result</button><a href="index.php" class="btn btn-link">Back</a></form></div></div></div></div></body></html>
